const sessionKey = filename => path.resolve(filename).toLowerCase();
function safe(value) { return JSON.stringify(value).replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/&/g, '\\u0026'); }
function clean(value) { return String(value || '').replace(/\s*;.*/, '').trim().replace(/^['"]|['"]$/g, ''); }
function currentText(filename) { const open = vscode.workspace.textDocuments.find(doc => path.resolve(doc.fileName).toLowerCase() === path.resolve(filename).toLowerCase()); return open ? open.getText() : fs.readFileSync(filename, 'utf8'); }
function throwDraftKey(defPath) { return `throw:${sessionKey(defPath)}`; }
function safeThrowDraft(value) { try { if (!value || typeof value !== 'object') return null; return { plan: normalizedPlan(value.plan) }; } catch (_) { return null; } }
function throwReference(defPath, plan) { const normalized=normalizedPlan(plan);return{defPath:path.resolve(defPath),planId:normalized.id,p1Action:Number(normalized.p1Action),p2Action:Number(normalized.p2Action)}; }
function validThrowReference(reference,defPath,model){return Boolean(reference&&typeof reference.defPath==='string'&&sessionKey(reference.defPath)===sessionKey(defPath)&&typeof reference.planId==='string'&&reference.planId&&model?.plan?.id===reference.planId&&model.actions.some(item=>item.action===Number(reference.p1Action))&&model.actions.some(item=>item.action===Number(reference.p2Action)));}

function characterAssets(defPath) {
  const text = fs.readFileSync(defPath, 'utf8'), folder = path.dirname(defPath), find = name => new RegExp(`^\\s*${name}\\s*=\\s*(.+?)\\s*$`, 'im').exec(text);
  const resolve = match => match ? path.resolve(folder, clean(match[1]).replace(/[\\/]/g, path.sep)) : '';
  const air = resolve(find('anim')), sff = resolve(find('sprite'));
  if (!air || !sff || !fs.existsSync(air) || !fs.existsSync(sff)) throw new Error('The character DEF must resolve existing anim and sprite files.');
  return { defPath, folder, air, sff };
}

function planDirectory(folder) { return path.join(folder, '.ikemen-tools', 'throw-plans'); }

function previewProfileSource(plan, enabled = true) {
  const bind = plan.events.filter(event => event.type === 'bind').sort((a, b) => a.tick - b.tick)[0] || { x: 35, y: 0 };
  const half = Number(bind.x || 0) / 2, y = Number(bind.y || 0);
  return `# IKEMEN Tools temporary live authoring profile\n# Generated by Throw Creator. Training-only; remove or disable after the preview.\n[StateDef -4]\n\nignoreHitPause if ${enabled ? 1 : 0} && !isHelper && gameMode = "training" && !map(IkTools_Profile_Applied) {\n\tmap(IkTools_Profile_Applied) := 1;\n\tvelSet{x: 0; y: 0}\n\tif playerNo = 1 {\n\t\tposSet{x: ${-half}; y: 0}\n\t\tif facing != ${Number(plan.p1Facing) || 1} { turn{} }\n\t\tif selfAnimExist(${Number(plan.p1Action)}) { changeAnim{value: ${Number(plan.p1Action)}} }\n\t} else if playerNo = 2 {\n\t\tposSet{x: ${half}; y: ${y}}\n\t\tif facing != ${Number(plan.p2Facing) || -1} { turn{} }\n\t\tif selfAnimExist(${Number(plan.p2Action)}) { changeAnim{value: ${Number(plan.p2Action)}} }\n\t}\n}\n`;
}

function linkedPreviewProfile(assets, plan, enabled) {
  const defText = fs.readFileSync(assets.defPath, 'utf8'), document = parseDef(defText, assets.defPath), files = sections(document, 'Files')[0];
  if (!files) throw new Error('The character DEF has no [Files] section.');
  const target = path.join(assets.folder, 'tools', 'ikemen-tools', 'ikemen_tools_preview_profile.zss'), relative = path.relative(assets.folder, target).replace(/\\/g, '/');
  const existing = (files.entries || []).find(entry => clean(entry.value).replace(/\\/g, '/').toLowerCase() === relative.toLowerCase());
  const key = existing?.key || nextStateFileKey(files), nextDef = existing ? defText : setSectionEntry(document, files.line, key, relative);
  return { target, source: previewProfileSource(plan, enabled), nextDef, linked: Boolean(existing), key };
}
function availablePlans(folder) {
  const directory = planDirectory(folder); if (!fs.existsSync(directory)) return [];
  return fs.readdirSync(directory).filter(name => /\.json$/i.test(name)).map(name => {
    const filename = path.join(directory, name);
    try { const plan = normalizedPlan(JSON.parse(fs.readFileSync(filename, 'utf8'))); return { id: plan.id, name: plan.name, filename }; } catch (_) { return null; }
  }).filter(Boolean).sort((a, b) => a.name.localeCompare(b.name));
}

function enrichTrack(track, archive, palette) {
  if (!track) return null;
  return { ...track, frames: track.frames.map(frame => {
    const sprite = archive.sprites.find(item => item.group === frame.group && item.number === frame.index); let image = null;
    if (sprite) try { image = { src: spriteDataUri(archive, sprite, palette), axisX: sprite.axisX, axisY: sprite.axisY, width: sprite.width, height: sprite.height }; } catch (_) {}
    return { ...frame, image };
  }) };
}

function workspaceModel(assets, plan) {
  const airText = currentText(assets.air), tracks = actionTracks(airText), archive = readSff(assets.sff), palette = assignedDefault(archive, assets.sff).index;
  const resolved = normalizedPlan(plan), p1 = tracks.find(track => track.action === Number(resolved.p1Action)) || tracks[0] || null, p2 = tracks.find(track => track.action === Number(resolved.p2Action)) || tracks[1] || tracks[0] || null;
  if (p1 && !tracks.some(track => track.action === Number(resolved.p1Action))) resolved.p1Action = p1.action;
  if (p2 && !tracks.some(track => track.action === Number(resolved.p2Action))) resolved.p2Action = p2.action;
  resolved.endTick = Math.max(1, Number(resolved.endTick) || p1?.totalTicks || 1);
  resolved.sourceHashes = { ...(resolved.sourceHashes || {}), air: hash(airText), sff: hash(fs.readFileSync(assets.sff)) };
  const checked = validatePlan(resolved, tracks);
  const partTracks = {};
  for (const part of resolved.parts) {
    const track = tracks.find(item => item.action === Number(part.anim));
    if (track && !partTracks[part.anim]) partTracks[part.anim] = enrichTrack(track, archive, palette);
  }
  return {
    character: path.basename(assets.folder), files: assets, plan: resolved, plans: availablePlans(assets.folder),
    actions: tracks.map(track => ({ action: track.action, elements: track.frames.length, ticks: track.totalTicks })),
    p1: enrichTrack(p1, archive, palette), p2: enrichTrack(p2, archive, palette), partTracks, issues: checked.issues,
    eventTypes: EVENT_TYPES, lanes: LANES, templates: Object.entries(TEMPLATES).map(([id, value]) => ({ id, label: value.label }))
  };
}

