function saveInputs(){plan.name=$('name').value;plan.template=$('template').value;for(const id of ['p1Action','p2Action','p1State','p2State','handoffState','startTick','endTick','loopStart','loopEnd','p1Facing','p2Facing'])plan[id]=Number($(id).value);for(const id of ['p1Type','p1Physics','p2Type','p2Physics'])plan[id]=$(id).value;plan.timingMode=$('timingMode').value;plan.holdLastP2=$('holdLastP2').checked;plan.notes=$('notes').value}
