  if (message.type === 'openExplodComposer') return vscode.commands.executeCommand('ikemen.explodComposer.open', vscode.Uri.file(session.assets.defPath));
  if (message.type === 'openPositionCamera') return vscode.commands.executeCommand('ikemen.positionCamera.open', vscode.Uri.file(session.assets.defPath));
